package party.lemons.biomemakeover.client.render;
import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.entity.*;import net.minecraft.resources.ResourceLocation;import party.lemons.biomemakeover.BiomeMakeover;import party.lemons.biomemakeover.client.model.*;import party.lemons.biomemakeover.client.sound.MothLoopSound;import party.lemons.biomemakeover.entity.MothEntity;
public final class MothRenderer extends MobRenderer<MothEntity,MothRenderState,MothModel>{private static final ResourceLocation TEX=BiomeMakeover.id("textures/entity/moth.png");public MothRenderer(EntityRendererProvider.Context c){super(c,new MothModel(c.bakeLayer(BMModelLayers.MOTH)),.25F);}@Override public MothRenderState createRenderState(){return new MothRenderState();}@Override public void extractRenderState(MothEntity e,MothRenderState s,float p){super.extractRenderState(e,s,p);s.bodyPitch=e.bodyPitch(p);if(!e.hasPlayedLoop){e.hasPlayedLoop=true;Minecraft.getInstance().getSoundManager().play(new MothLoopSound(e));}}@Override public ResourceLocation getTextureLocation(MothRenderState s){return TEX;}@Override protected void setupRotations(MothRenderState s,PoseStack p,float y,float scale){super.setupRotations(s,p,y,scale);p.translate(0,.25F,0);}}
